   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>

     <script>
       const fields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           required: true,
           autocomplete: "name",
           placeholder: "Jane Doe",
           validate(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           }
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           required: true,
           autocomplete: "email",
           placeholder: "jane@example.com",
           validate(value) {
             const trimmedValue = value.trim();
             if (!trimmedValue) {
               return "Error: Enter your email address.";
             }

             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)
               ? ""
               : "Error: Enter a valid email address, like jane@example.com.";
           }
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           required: false,
           autocomplete: "tel",
           placeholder: "555-123-4567",
           helperText: "Use 10 digits, such as 555-123-4567. Country codes are optional.",
           validate(value) {
             const trimmedValue = value.trim();
             if (!trimmedValue) {
               return "";
             }

             return /^\+?[0-9][0-9\s().-]{7,18}[0-9]$/.test(trimmedValue)
               ? ""
               : "Error: Enter a phone number like 555-123-4567 or +1 555-123-4567.";
           }
         }
       ];

       const formState = fields.reduce((state, field) => {
         state[field.name] = "";
         return state;
       }, {});

       const escapeHtml = (value) =>
         String(value).replace(/[&<>"']/g, (character) => {
           const entities = {
             "&": "&amp;",
             "<": "&lt;",
             ">": "&gt;",
             '"': "&quot;",
             "'": "&#039;"
           };
           return entities[character];
         });

       function FormField(field) {
         const errorId = `${field.id}-error`;
         const helperId = field.helperText ? `${field.id}-helper` : "";
         const describedBy = [helperId, errorId].filter(Boolean).join(" ");
         const requiredText = field.required
           ? '<span class="required-marker" aria-hidden="true">*</span>'
           : '<span class="optional-text">(optional)</span>';

         return `
           <div class="form-field">
             <label for="${field.id}">${field.label} ${requiredText}</label>
             <input
               id="${field.id}"
               name="${field.name}"
               type="${field.type}"
               autocomplete="${field.autocomplete}"
               placeholder="${field.placeholder}"
               ${field.required ? "required" : ""}
               aria-describedby="${describedBy}"
               aria-invalid="false"
             >
             ${
               field.helperText
                 ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>`
                 : ""
             }
             <p class="error-message" id="${errorId}"></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <main id="main-content">
             <section class="support-card" aria-labelledby="support-title">
               <div class="card-header">
                 <p class="eyebrow">Support</p>
                 <h1 id="support-title">Contact our team</h1>
                 <p class="intro">
                   Tell us how to reach you and we will connect you with the right support specialist.
                 </p>
               </div>
               <form id="support-form" novalidate>
                 <p class="required-note">
                   Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
                 </p>
                 ${fields.map(FormField).join("")}
                 <div class="button-row">
                   <button type="submit">Send request</button>
                   <p class="status-message" id="form-status" aria-live="polite"></p>
                 </div>
               </form>
             </section>
           </main>
         `;
       }

       function App() {
         return `<div class="page-shell">${ContactForm()}</div>`;
       }

       function validateField(field) {
         const input = document.getElementById(field.id);
         const errorElement = document.getElementById(`${field.id}-error`);
         const error = field.validate(input.value);

         input.setAttribute("aria-invalid", error ? "true" : "false");
         errorElement.textContent = error;
         errorElement.classList.toggle("is-visible", Boolean(error));

         return error;
       }

       function initializeContactForm() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         fields.forEach((field) => {
           const input = document.getElementById(field.id);

           input.addEventListener("input", (event) => {
             formState[field.name] = event.target.value;

             if (input.getAttribute("aria-invalid") === "true") {
               validateField(field);
             }

             status.textContent = "";
           });

           input.addEventListener("blur", () => {
             validateField(field);
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();

           const firstInvalidField = fields.find((field) => validateField(field));

           if (firstInvalidField) {
             document.getElementById(firstInvalidField.id).focus();
             status.textContent = "";
             return;
           }

           status.textContent = "Your support request is ready to send.";
           form.reset();

           fields.forEach((field) => {
             formState[field.name] = "";
           });
         });
       }

       document.getElementById("app").innerHTML = App();
       initializeContactForm();
     </script>
   </body>
 </html>

