         border-radius: 0.75rem;
         background: var(--error-bg);
         color: var(--error);
         padding: 0.65rem 0.75rem;
       }

       .error-message.is-visible {
         display: block;
       }

       .button-row {
         display: flex;
         flex-wrap: wrap;
         align-items: center;
         gap: 1rem;
         padding-top: 0.25rem;
       }

       button {
         min-height: 3.25rem;
         min-width: 10rem;
         border: 0;
         border-radius: 999px;
         background: linear-gradient(135deg, var(--accent), #a78bfa);
         color: #07111f;
         cursor: pointer;
         font: inherit;
         font-weight: 900;
         padding: 0.9rem 1.4rem;
         transition:
           transform 160ms ease,
           box-shadow 160ms ease;
       }

       button:hover {
         box-shadow: 0 14px 30px rgb(56 189 248 / 0.22);
         transform: translateY(-1px);
       }

       button:focus {
         outline: 3px solid #ffffff;
         outline-offset: 4px;
       }

       button:active {
         transform: translateY(0);
